let DATA,shop,action='none',tab='cash',base,result;
const $=id=>document.getElementById(id),money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}),day=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace(/\.$/,'');
const choices=[['none','Manter cenário atual','Comparar sem alterar pagamentos'],['negotiate','Negociar com fornecedor','Mover a próxima compra em 7 dias'],['reduce','Reduzir gastos variáveis','Simular economia de 10% por 60 dias'],['advance','Antecipar recebíveis','Comparar custo e entradas futuras'],['mix','Ajustar o mix de venda','Desconto no Pix e parcelamento máximo']];
function opts(){return {balance:Number($('balance').value),shock:Number($('shock').value),advance:Number($('advance').value),pixDiscount:Number($('pixDiscount').value),maxInstall:Number($('maxInstall').value),action};}
function changeShop(id){shop=DATA.shops.find(s=>s.id===id);$('shop').value=id;$('balance').value=shop.balance;$('shock').value=0;$('advance').value=3000;$('pixDiscount').value=2;$('maxInstall').value=shop.installments??4;action='none';$('planStatus').textContent='';render();}
function render(){
 $('profile').textContent=shop.sector+' · '+shop.age+' meses de operação';$('shockValue').textContent=$('shock').value+'%';
 base=simulate(shop,DATA,{...opts(),action:'none'});result=simulate(shop,DATA,opts());
 const h=Number($('horizon').value), visible=result.daily.slice(0,h),negative=visible.find(d=>d.balance<0);
 const u=shop.uncertainty,off=Number($('balance').value)-shop.balance,hz=u.horizons[String(h)],q=u.quantiles;
 const minLo=Math.min(...q.q2_5.slice(0,h))+off,minHi=Math.min(...q.q97_5.slice(0,h))+off;
 const pos=Math.round(hz.probPositiveClose*100),neg=Math.round(hz.probNegative*100);
 $('metrics').innerHTML=[
  ['Menor saldo provável ('+h+' dias)',money(minLo)+' a '+money(minHi),'Faixa de 95% (p2,5–p97,5) · '+u.scenarios+' cenários',minLo<0],
  ['Chance de fechar no azul',pos+'%','Saldo positivo ao fim dos '+h+' dias',pos<50],
  ['Risco de ficar negativo',neg+'%',hz.firstNegativeDay?'1º negativo mais provável em '+day(hz.firstNegativeDay):'Nenhum cenário fica negativo',neg>=50],
  ['Buraco: mediano / p95',hz.medianHole<0?money(hz.medianHole)+' / '+money(hz.p95Hole):'Sem buraco',hz.medianHole<0?'Pior saldo típico e cauda ruim (p95)':'Saldo positivo em todos os cenários',hz.medianHole<0]
 ].map(([l,v,s,w])=>`<article class="metric ${w?'warn':''}"><span class="label">${l}</span><strong class="${v.length>13?'text-value':''}">${v}</strong><small>${s}</small></article>`).join('');
 $('actions').innerHTML=choices.map(([id,title,sub])=>`<label class="choice"><input type="radio" name="action" value="${id}" ${action===id?'checked':''}>${title}<small>${sub}</small></label>`).join('');
 document.querySelectorAll('[name=action]').forEach(el=>el.onchange=()=>{action=el.value;$('planStatus').textContent='';render();});
 $('advanceBox').hidden=action!=='advance';$('mixBox').hidden=action!=='mix';
 const details={none:'Selecione uma alternativa e compare o saldo. Nenhuma contratação ou transação é executada.',negotiate:`${money(result.shifted)} transferidos por 7 dias. Depende de aceite do fornecedor; hipótese sem multa. O pagamento continua no fluxo.`,reduce:'Hipótese: reduzir 10% dos gastos operacionais variáveis sem alterar vendas. Verifique se a economia é viável e se afeta a operação.',advance:`${money(result.advanced)} brutos antecipados; custo de ${money(result.fee)}. Taxa ilustrativa de 2,5% a cada 30 dias, proporcional ao prazo. Os recebíveis utilizados são retirados das datas originais.`,mix:`Hipóteses de elasticidade: cada 1% de desconto no Pix migra 6 p.p. do crédito para Pix; cada parcela abaixo da base (${shop.installments??4}x) reduz o volume parcelado em 8%. Com ${$('pixDiscount').value}% de desconto e parcelamento em ${$('maxInstall').value}x, muda a modalidade, o prazo e o volume das vendas. Custo total (desconto no Pix + vendas parceladas perdidas): ${money(result.fee)}.`};
 const margemVeto=action==='advance'&&hz.diagnosis==='margem';
 $('actionDetail').textContent=(margemVeto?'Não recomendado neste diagnóstico (margem): antecipar não resolve, só adia o aperto e cobra taxa. ':'')+details[action];
 $('plan').disabled=action==='none';$('plan').style.opacity=action==='none'?'.5':'1';
 $('insight').textContent=negative?`O cenário indica saldo abaixo de zero em ${day(negative.date)}. Compare entradas e despesas nessa data antes de escolher uma ação.`:`O cenário mantém saldo positivo nos ${h} dias exibidos. Acompanhe o fluxo: vendas futuras ainda são estimativas.`;
 draw(h);renderCopilot();renderDetail();
}
function draw(h){
 const a=base.daily.slice(0,h),b=result.daily.slice(0,h),W=850,H=290,L=72,R=18,T=20,B=38;
 const u=shop.uncertainty,off=Number($('balance').value)-shop.balance,q=u.quantiles,qq=k=>q[k].slice(0,h).map(v=>v+off);
 const lo=qq('q2_5'),inLo=qq('q25'),med=qq('q50'),inHi=qq('q75'),hi=qq('q97_5');
 const values=[0,...a.map(d=>d.balance),...b.map(d=>d.balance),...lo,...hi],loV=Math.min(...values),hiV=Math.max(...values),pad=Math.max(1000,(hiV-loV)*.12),mn=loV-pad,mx=hiV+pad;
 const x=i=>L+i*(W-L-R)/(h-1),y=v=>T+(mx-v)/(mx-mn)*(H-T-B);
 const poly=(hiArr,loArr)=>hiArr.map((v,i)=>x(i)+','+y(v)).concat(loArr.map((v,i)=>x(i)+','+y(v)).reverse()).join(' ');
 let svg=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg"><title>Saldo diário projetado: faixa de 95% (p2,5–p97,5), faixa de 50% (p25–p75), mediana, cenário atual e simulação.</title>`;
 if(loV<0)svg+=`<rect x="${L}" y="${y(0)}" width="${W-L-R}" height="${H-B-y(0)}" fill="#fff4eb"/>`;
 for(let i=0;i<5;i++){const v=mn+(mx-mn)*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e4edf1"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end" font-size="12" fill="#617989">${(v/1000).toFixed(1)} mil</text>`;}
 svg+=`<line x1="${L}" x2="${W-R}" y1="${y(0)}" y2="${y(0)}" stroke="#b58961" stroke-dasharray="4 4"/>`;
 svg+=`<polygon points="${poly(hi,lo)}" fill="#029b87" fill-opacity="0.10"/>`;
 svg+=`<polygon points="${poly(inHi,inLo)}" fill="#029b87" fill-opacity="0.18"/>`;
 svg+=`<polyline points="${med.map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="#029b87" stroke-width="1.5" stroke-dasharray="2 3" stroke-opacity=".65"/>`;
 for(const [arr,color,width,dash] of [[a,'#8095a3',2,'5 4'],[b,'#029b87',3,'']])svg+=`<polyline points="${arr.map((d,i)=>x(i)+','+y(d.balance)).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" stroke-dasharray="${dash}" stroke-linejoin="round"/>`;
 for(const i of [0,Math.floor(h/3),Math.floor(2*h/3),h-1])svg+=`<text x="${x(i)}" y="${H-8}" text-anchor="middle" font-size="12" fill="#617989">${day(a[i].date)}</text>`;
 $('chart').innerHTML=svg+'</svg>';
 $('chart').setAttribute('aria-label',`Gráfico de ${h} dias com faixa de 95% do saldo. No pior dia, a faixa vai de ${money(Math.min(...lo))} a ${money(Math.min(...hi))}. Valores diários na tabela abaixo.`);
}
function renderDetail(){
 document.querySelectorAll('[data-tab]').forEach(el=>el.setAttribute('aria-selected',String(el.dataset.tab===tab)));
 if(customDetail())return;
 if(tab==='cash'){$('detail').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Recebíveis existentes</th><th>Novas vendas liquidadas</th><th>Saídas</th><th>Saldo</th></tr></thead><tbody>${result.daily.slice(0,Number($('horizon').value)).map(d=>`<tr><td>${day(d.date)}</td><td>${money(d.existing)}</td><td>${money(d.newSales)}</td><td>${money(d.expense)}</td><td class="${d.balance<0?'negative':''}">${money(d.balance)}</td></tr>`).join('')}</tbody></table></div><button id="export" class="secondary" style="margin-top:15px">Exportar este fluxo (CSV)</button>`;$('export').onclick=exportFlow;}
 if(tab==='model') {let m=shop.metrics;$('detail').innerHTML=`<div class="model-grid"><div><h3>Random Forest treinada de verdade</h3><p>100 árvores combinam histórico e calendário para prever 60 dias de vendas. Cada negócio tem seu próprio modelo, treinado em Python com 620 dias sintéticos.</p><p><strong>Erro médio por dia: ${money(m.mae)}</strong><br>Referência simples (repetir última semana): ${money(m.baselineMae)}.</p><p class="small">Teste reservado: ${day(m.testStart)} a ${day(m.testEnd)} de 2026. ${m.trainSamples} exemplos de treino com alvos anteriores ao teste. Avaliação em um único período: não comprova desempenho real. O modelo final usa o histórico completo. As previsões já calculadas são carregadas nesta demonstração; a página não retreina o modelo.</p></div><div><h3>Variáveis usadas pela floresta</h3>${shop.importance.slice(0,6).map(v=>`<div class="bar"><span>${v.name}</span><i style="width:${Math.max(2,v.value*100)}%"></i><span>${Math.round(v.value*100)}%</span></div>`).join('')}<p class="small">Importância global por redução de impureza. Não indica causalidade nem explica isoladamente uma previsão. Não é um modelo de probabilidade de falência.</p><a class="download" href="prototipo-faro.zip" download>Baixar código e dados</a></div></div>`;}
 if(tab==='source')$('detail').innerHTML=`<div class="source-grid"><div><h3>Dados simulados de pagamentos</h3><p>Vendas diárias por modalidade, taxas, parcelamento e agenda de recebíveis. Representam categorias de dados de uma adquirente, sem reproduzir um esquema ou contrato real da Cielo.</p><p class="small">Pix: D+0; débito: D+1; crédito à vista: D+30; parcelado: 3 recebimentos em D+30/60/90. Calendário simplificado em dias corridos, sem feriados, chargebacks ou cancelamentos.</p><a class="download" href="pagamentos_sinteticos.csv" download>Baixar pagamentos sintéticos</a></div><div><h3>Informações complementares do lojista</h3><p>Saldo inicial e despesas com operação, fornecedores e custos fixos são hipóteses informadas pelo lojista. Não são inferidas como dados disponíveis à Cielo.</p><p class="small">A demonstração considera que todas as vendas do negócio passam pelos meios simulados. Em uso real, seria necessário conciliar outros bancos e adquirentes. Recebíveis após os 60 dias continuam fora da janela exibida. Nenhum dado pessoal ou real foi utilizado.</p></div></div>`;
}
function exportFlow(){if(coverage==='payments')return;const text='data;recebiveis_existentes;novas_vendas_liquidadas;saidas;saldo\n'+result.daily.map(d=>[d.date,d.existing,d.newSales,d.expense,d.balance].map(v=>typeof v==='number'?v.toFixed(2).replace('.',','):v).join(';')).join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='fluxo-'+shop.id+'-60-dias.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
fetch('data.json').then(r=>{if(!r.ok)throw Error('Dados indisponíveis');return r.json();}).then(data=>{DATA=data;$('shop').innerHTML=data.shops.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');changeShop(data.shops[0].id);$('coverage').onchange=()=>setCoverage($('coverage').value);$('shop').onchange=()=>changeShop($('shop').value);for(const id of ['balance','shock','horizon','advance','pixDiscount'])$(id).oninput=()=>{if(['balance','advance','pixDiscount'].includes(id)&&(!$(id).validity.valid||$(id).value===''))return;$('planStatus').textContent='';render();};$('maxInstall').onchange=()=>{$('planStatus').textContent='';render();};$('reset').onclick=()=>changeShop(shop.id);document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;renderDetail();});$('plan').onclick=()=>{$('planStatus').textContent='Plano desta sessão: '+choices.find(c=>c[0]===action)[1]+'. Simulação registrada; depende de análise e execução do lojista. Não é salva após recarregar.';};
 if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'simulate_cash_scenario',description:'Configura o cenário de caixa visível; não executa transações.',inputSchema:{type:'object',properties:{shopId:{type:'string',enum:data.shops.map(s=>s.id)},action:{type:'string',enum:choices.map(c=>c[0])}},required:['shopId','action'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(coverage==='payments')throw Error('Complete os dados antes de simular caixa');if(!input||!data.shops.some(s=>s.id===input.shopId)||!choices.some(c=>c[0]===input.action))throw Error('Cenário inválido');changeShop(input.shopId);action=input.action;render();return{min:result.min,end:result.end,firstNegative:result.firstNegative};}})).catch(()=>{});}catch(e){}
}).catch(e=>{$('metrics').textContent='Não foi possível carregar os dados. Recarregue a página.';console.error(e);});
